Use ASP.NET Core's **`WebApplicationFactory<TEntryPoint>`** from the `Microsoft.AspNetCore.Mvc.Testing` package. It spins up your app in-memory with no real network port.

### Setup

```bash
dotnet add tests/MyMcp.Tests package Microsoft.AspNetCore.Mvc.Testing
```

### Test pattern

```csharp
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using System.Text.Json;

public class McpIntegrationTests
    : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.True(body.TryGetProperty("result", out var result));
        Assert.True(result.TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        // Initialize session first (Streamable HTTP needs session)
        var init = new { jsonrpc = "2.0", id = 1, method = "initialize",
            @params = new { protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test", version = "1.0" } } };
        var initResp = await _client.PostAsJsonAsync("/mcp", init);
        var sessionId = initResp.Headers
            .GetValues("Mcp-Session-Id").FirstOrDefault();

        // List tools
        var req = new HttpRequestMessage(HttpMethod.Post, "/mcp")
        {
            Content = JsonContent.Create(new
            {
                jsonrpc = "2.0", id = 2, method = "tools/list"
            })
        };
        if (sessionId != null)
            req.Headers.Add("Mcp-Session-Id", sessionId);

        var resp = await _client.SendAsync(req);
        resp.EnsureSuccessStatusCode();

        var body = await resp.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

### Key points

- **`WebApplicationFactory`** hosts your real `Program`/`Startup` in-process — middleware, DI, routing all run as normal.
- **No port binding** — `CreateClient()` returns an `HttpClient` wired to an in-memory transport.
- Override services (e.g., swap a database) via `factory.WithWebHostBuilder(b => b.ConfigureServices(...))`.
- Make sure `Program` is accessible to the test project (add `InternalsVisibleTo` or a `public partial class Program { }` marker).
- If your server uses **SSE streaming**, read the response stream incrementally instead of `ReadFromJsonAsync`.
